/*
 * A042383  Denominators of continued fraction convergents to sqrt(718).
 * https://oeis.org/A042383
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) is the denominator of the nth continued fraction convergent
 *            of sqrt(718). Let a₀ = ⌊√718⌋ = 26. Partial quotients aₖ for k ≥
 *            1 are generated by the continued‑fraction recurrence: m₀ = 0, d₀
 *            = 1 For k ≥ 1: mₖ = dₖ₋₁·aₖ₋₁ – mₖ₋₁ dₖ = (718 – mₖ²) / dₖ₋₁ aₖ
 *            = ⌊(26 + mₖ) / dₖ⌋ Convergents satisfy...
 * Range:     u8 n <= 4, u16 n <= 11, u32 n <= 20, u64 n <= 41, u128 n <= 81,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    const seq_t a0 = 26;           /* floor(sqrt(718)) */
    if (n == (idx_t)0)
        return (seq_t)1;           /* q0 = 1 */

    unsigned long long m = 0, d = 1;   /* m₀, d₀ */
    seq_t a_curr = a0;                /* a₀ initially */

    seq_t p_prev2 = (seq_t)0, p_prev1 = (seq_t)1;
    seq_t q_prev2 = (seq_t)1, q_prev1 = (seq_t)0;

    for (idx_t k = (idx_t)0; k <= n; ++k) {
        /* compute convergent k */
        seq_t p_curr = a_curr * p_prev1 + p_prev2;
        seq_t q_curr = a_curr * q_prev1 + q_prev2;

        if (k == n)
            return q_curr;

        /* compute next partial quotient a_{k+1} */
        unsigned long long m_new = d * (unsigned long long)a_curr - m;
        unsigned long long d_new = (718ULL - m_new * m_new) / d;

        m = m_new;
        d = d_new;
        a_curr = (seq_t)((a0 + (seq_t)m) / (seq_t)d);

        /* shift previous terms */
        p_prev2 = p_prev1;
        p_prev1 = p_curr;
        q_prev2 = q_prev1;
        q_prev1 = q_curr;
    }
    /* unreachable */
    return (seq_t)0;
}
